// Preparation-bound organ physiology; catalogue classes supply no causal or numerical defaults.
const extent = "selected-primary-results-methods-and-figure-legends-supplement-unread";
const commonLimit = "Primary source interpretation only: no raw-data replay, laboratory reproduction, independent scientific review, evolutionary origin reconstruction or universal organism-count/causal-weight admission.";
const sources = [];
const entities = [];
const claims = [];
const relations = [];
const studies = [];
const comparisons = [];
const readiness = [];
const sourceIndex = new Map();
const studyIndex = new Map();
const findingIndex = new Map();

function publication(id, title, authors, year, doi, pmcid, journal, volume, issue, pages, locators, limit, correction = "No explicit correction was identified in the inspected primary article record and available DOI metadata. This limited check does not establish absence of corrections.") {
  const source = { id, kind: "research-publication", title, authors, year, doi,
    url: pmcid ? `https://pmc.ncbi.nlm.nih.gov/articles/${pmcid}/` : `https://doi.org/${doi}`,
    path: null, sha256: null, review: { extent, locators, limit } };
  sources.push(source);
  sourceIndex.set(id, { source, journal, volume, issue, pages, correction });
}
function citation(sourceId, locator, role = "supports") {
  return { sourceId, locator, role, note: "Read primary passage within its declared review extent; preparation, comparison and uncertainty remain local to this publication." };
}
function node(id, name, kind, statement, claimIds, coordinates, obligations = [], status = "evidence-scoped") {
  entities.push({ id: `org:${id}`, name, kind, description: statement, claimIds, status,
    sourceCoordinates: coordinates, openObligations: [...obligations, commonLimit], level: 5 });
  readiness.push({ nodeId: `org:${id}`, role: kind === "context" ? "experimental-context" : kind === "definition" ? "definition" : "scoped-phenomenon",
    denotes: statement, instanceAdmission: "none", claimIds });
  return `org:${id}`;
}
function study(id, sourceId, system, preparation, observable, finding, limitations, studyType = "primary-experiment", locatorIndexes = null) {
  const meta = sourceIndex.get(sourceId);
  const locators = locatorIndexes ? locatorIndexes.map((i) => meta.source.review.locators[i]) : meta.source.review.locators;
  const methodId = `M-org-${id}`;
  const limits = [meta.source.review.limit, ...limitations, commonLimit];
  claims.push({ id: methodId, kind: "method", statement: preparation, scope: system,
    status: "method-contract", citations: locators.map((locator) => citation(sourceId, locator, "method")), checkIds: [], limitations: limits, contextIds: [id] });
  const contextNodeId = node(`${id}-context`, `${id}: acquisition context`, "context", preparation, [methodId], locators.map((locator) => ({ sourceId, locator })), limits, "definition");
  if (studyType === "computational-analysis") readiness.find((record) => record.nodeId === contextNodeId).role = "model-context";
  const record = { id, sourceId, studyType, doi: meta.source.doi, journal: meta.journal, volume: meta.volume,
    issue: meta.issue, pages: meta.pages, system, preparation, observable, finding, limitations: limits,
    readExtent: extent, reviewedLocators: locators, metadataCheckedAt: "2026-10-22", metadataUrl: `https://doi.org/${meta.source.doi}`,
    correctionCheck: meta.correction };
  studies.push(record);
  studyIndex.set(id, { record, methodId, limits, locators });
}
function observation(id, name, studyId, statement, extraLimits = [], status = "publication-supported") {
  const context = studyIndex.get(studyId);
  const claimId = `C-org-${id}`;
  claims.push({ id: claimId, kind: "review-finding", statement, scope: context.record.system, status,
    citations: context.locators.map((locator) => citation(context.record.sourceId, locator)), checkIds: [],
    limitations: [...context.limits, ...extraLimits], contextIds: [studyId] });
  node(id, name, "scoped-process", statement, [claimId, context.methodId], context.locators.map((locator) => ({ sourceId: context.record.sourceId, locator })), extraLimits);
  relations.push({ id: `organismal:${studyId}-measures-${id}`, source: `org:${studyId}-context`, target: `org:${id}`,
    kind: "descriptive", role: context.record.studyType === "computational-analysis" ? "computation-context" : "measurement-context", assertion: "This source context defines the preparation or analytical-input and readout boundary of the finding.",
    claimIds: [context.methodId, claimId], contextIds: [studyId] });
  findingIndex.set(id, { claimId, studyId });
  return claimId;
}
function operating(source, target, studyId, assertion, bearer, input, observable, limit) {
  const context = studyIndex.get(studyId);
  const a = findingIndex.get(source), b = findingIndex.get(target);
  relations.push({ id: `organismal:${source}-supports-${target}`, source: `org:${source}`, target: `org:${target}`,
    kind: "functional-support", role: "scoped-operating-support", assertion,
    claimIds: [...new Set([a.claimId, b.claimId, context.methodId])], contextIds: [studyId],
    carrier: { contextIds: [studyId], citations: context.locators.map((locator) => ({ sourceId: context.record.sourceId, locator })),
      interpretation: { bearer, input, observable, limit }, countingStatus: "unoperationalized", numericalAdmission: "none" } });
}

