const excludedDefaults = [
  'Original Level/Phase/TypeRole/Science/ScientificStatus classify catalogue concepts; they do not establish universal ontological stages, historical emergence or experimentally measured causal organization.',
  'Requirements MustCover/ShouldCover/OptionalCover codes do not prove empirical completeness or necessary physical modules.',
  'Original parent Weight values are not measured causal fractions; no normalized numerical weight is admitted.',
  'Original Necessity, DependencyType, OntologicalRole, CausalDirections and InteractionModes do not supply universal experimental laws or construction rules.',
  'Original Quantization CarrierGroupId/CarrierTypeId and N_min/N_crit/N_sat do not operationalize carrier counts, minimal tissue numbers, critical thresholds or saturation.',
  'Original Evidence entries without publication identifiers are leads rather than verified independent replications; generic review/theory/empirical labels do not substitute for actual primary preparation.'
];
export const CARD_SCOPES = [];
function card(index, originalName, slug, scope, findingIds, topics, parents, unresolved) {
  const findingClaims = findingIds.flatMap((id) => [findingIndex.get(id).claimId, ...(findingIndex.get(id).reusedClaimIds ?? [])]);
  const studiesForCard = [...new Set(findingIds.map((id) => findingIndex.get(id).studyId).filter(Boolean))];
  const sourceIds = [...new Set(findingIds.flatMap((id) => {
    const f = findingIndex.get(id); return f.studyId ? [studyIndex.get(f.studyId).record.sourceId] : f.sourceIds;
  }))];
  const claimId = `D-org-${slug}-scope`;
  const scientificCitations = sourceIds.flatMap((sourceId) => sourceId === 'song2012' ? songLocators.map((locator) => citation(sourceId, locator, 'limits')) : sourceIndex.get(sourceId).source.review.locators.map((locator) => citation(sourceId, locator, 'limits')));
  claims.push({ id: claimId, kind: 'review-finding', statement: scope,
    scope: `Reconstruction of catalogue card 5.${index}; only the named preparations with original assertions, ordered parents and defaults assessed separately.`,
    status: 'definition', citations: [citation('legacy-5', `/${index}`, 'provenance'), ...scientificCitations], checkIds: [],
    limitations: [...excludedDefaults, ...unresolved, commonLimit] });
  node(slug, `${originalName}: reviewed scope`, 'definition', scope, [claimId],
    [{ sourceId: 'legacy-5', locator: `/${index}` }, ...scientificCitations.map(({ sourceId, locator }) => ({ sourceId, locator }))], [...excludedDefaults, ...unresolved], 'definition');
  const allClaims = [claimId, ...findingClaims, ...studiesForCard.map((id) => studyIndex.get(id).methodId)];
  for (const findingId of findingIds) {
    const f = findingIndex.get(findingId);
    relations.push({ id: `organismal:${findingId}-interprets-${slug}`, source: `org:${findingId}`, target: `org:${slug}`,
      kind: 'descriptive', role: f.studyId ? 'interpretation-dependency' : 'definition-dependency', assertion: 'This source-scoped finding or existing evidence definition qualifies the catalogue concept without turning class membership into a physical causal relation.',
      claimIds: [claimId, f.claimId, ...(f.studyId ? [studyIndex.get(f.studyId).methodId] : [])], ...(f.studyId ? { contextIds: [f.studyId] } : {}) });
  }
  const qualify = ([topic, disposition, reason, selected]) => ({ topic, disposition, reason,
    claimIds: selected ? selected.map((id) => findingIndex.get(id)?.claimId ?? id) : [claimId, ...findingClaims] });
  CARD_SCOPES.push({ code: `5.${index}`, sourceIndex: index, originalName, scope,
    nodeIds: [`org:${slug}`, ...findingIds.map((id) => `org:${id}`), ...studiesForCard.map((id) => `org:${id}-context`)], claimIds: [...new Set(allClaims)],
    assertions: topics.map(qualify), parentDispositions: parents.map(([parentCode, disposition, reason, selected]) => ({ parentCode, disposition, reason, claimIds: qualify([parentCode, disposition, reason, selected]).claimIds })),
    excludedDefaults: [...excludedDefaults], unresolved });
}

card(5, 'Physiological Regulation and Organ Homeostasis', 'organ-homeostasis-scope',
  'Organ homeostasis is reconstructed through distinct mouse thermal-effector, drinking/fluid-signal and rat hormone-dynamics preparations. Defined perturbations and controls expose conditional neural, humoral, circulatory and cellular contributions. Stable capacity is an interpretive vocabulary for existing systems, not proof of one complete feedback architecture, universal operating range or historical generation of every organ. Anticipatory signals can change before blood correction, and stronger constant endocrine drive can change temporal regime rather than merely scale output.',
  ['coordinated-thermal-effectors', 'fluid-signal-pathway-separation', 'anticipation-precedes-blood-correction', 'saline-prediction-reversal', 'dose-dependent-endocrine-regime', 'circulation-not-cell-presence'],
  [['Stable organ function despite perturbations', 'qualified', 'Specified preparations show finite responses and return/recovery or compensation-related behavior; no whole-organ lifetime stability theorem or all-perturbation closure is measured.'],
   ['Pressure, temperature, chemical composition, flow and output', 'qualified', 'Thermal and osmotic/behavioral variables and selected circulatory responses have actual assays; pressure-related neural sensing is not proof of restored pressure and no complete clinical range atlas is admitted.'],
   ['Distributed signaling, structural coupling and maintenance', 'qualified', 'Specific neural/endocrine/flow examples support distinct components. Their union is a comparative view, not one experimentally isolated complete control circuit.'],
   ['Feedback as the only temporal regulatory logic', 'excluded', 'Anticipatory thirst signals precede systemic blood correction and can be revised by delayed composition information.'],
   ['Persistent property rather than single event or object', 'qualified', 'This is a scoped conceptual role describing capacity; an ontological classification is not itself an empirical discovery.'],
   ['All physiology preserved through one adaptive compensation rule', 'unresolved', 'The assays do not reconstruct all organ failure/recovery mechanisms, reserve capacity, immune contributions or a universal compensation bound.']],
  [['5.0', 'qualified', 'Existing tissue/circuit architecture is part of each bearer; these functional studies do not establish morphogenesis as a measured immediate causal input with a universal weight.'],
   ['4.6', 'qualified', 'Cellular conditions are included in the preparation; a generic homeostasis card is not an independently isolated upstream regulatory cause.'],
   ['4.3', 'qualified', 'Specified receptors/circuit transmission matter locally, but no single cellular-signaling necessity or contribution fraction is transferred.'],
   ['4.25', 'unresolved', 'Tonic cytokine input is not independently manipulated in the admitted thermal/fluid/endocrine cases.'],
   ['4.27', 'excluded', 'SASP is not a demonstrated necessary input of the healthy source preparations; possible disease-specific modulation requires its own evidence.'],
   ['5.22', 'unresolved', 'Tissue inflammatory microenvironments may modulate physiology, but their source-specific effect is not isolated in these cases.'],
   ['5.24', 'excluded', 'Chronic low-grade inflammation is not established as a prerequisite of normal organ homeostasis.'],
   ['5.25', 'unresolved', 'An immune-resilience trade-off is not measured by these neural/endocrine functional assays.'],
   ['4.28', 'unresolved', 'Macrophage program contributions to the measured organ variables are not isolated here.'],
   ['4.31', 'unresolved', 'No generic mTOR/autophagy/senescence pathway is demonstrated as necessary for each homeostatic response.']],
  ['Define and test matched whole-path loops, longitudinal bounds and additional organ systems before asserting complete physiological closure.']);

card(6, 'Development of the Vascular System and Tissue Perfusion', 'vascular-development-perfusion-scope',
  'Vascular organization is reconstructed as developmental guidance/remodeling and adult cerebral response cases with distinct scales and readouts. Retinal VEGF patterning can dissociate directed growth from proliferation; yolk-sac viscosity rescue distinguishes mechanical flow contributions from circulating erythroblast presence; adult mural-cell attribution remains preparation-dependent and contested. A branching anatomical network, patent lumen, blood-cell presence, transport rate, exchange and organ oxygenation are separate properties.',
  ['retinal-filopodia-response', 'vascular-guidance-versus-growth', 'vascular-lumen-tip-boundary', 'circulation-not-cell-presence', 'vascular-remodeling-rescue', 'hall-sensory-perfusion-response', 'mural-contractility-positive-and-null', 'perfusion-mechanism-unresolved'],
  [['Identifiable branching transport-network anatomy', 'supported', 'Retinal sprouts, vessel segments and yolk-sac hierarchical remodeling are directly imaged in the named preparations.'],
   ['Oxygen, nutrient, metabolite and hormone distribution', 'qualified', 'Patent lumina/flow and separate nutrient/hormone cases support distinct transport contexts; all transported classes and tissue oxygen-delivery adequacy are not measured in every vascular assay.'],
   ['Guidance, branching, lumen formation and selective remodeling', 'qualified', 'VEGF guidance and hemodynamic remodeling have distinct source support. Lumen observations do not provide a complete lumen-generation mechanism or all pruning/stabilization pathways.'],
   ['Growth automatically yields functional network', 'excluded', 'Altered VEGF distribution can enlarge or hyperfuse vessels while impairing directed patterning; present cells/channels do not guarantee normal through-flow.'],
   ['Local demand precisely determines adult perfusion effector', 'qualified', 'Sensory stimulation changes cerebral vessels, but pericyte versus smooth-muscle attribution depends on source classification and state, without a universal demand-to-flow transfer function.'],
   ['Vascular transport is universally required for all multicellular scale', 'excluded', 'The selected vertebrate cases do not prove that every multicellular organism or tissue must use this architecture, or identify a universal size threshold.'],
   ['Stable anatomical object and ontological origin', 'qualified', 'An object label describes observed networks; it does not reconstruct evolutionary origin or a single timeless stage.']],
  [['5.0', 'qualified', 'Source morphogenesis includes a preexisting astrocyte scaffold and embryonic plexus, not a universally weighted necessary parent from an abstract tissue-pattern card.'],
   ['4.6', 'qualified', 'Oxygenation/culture conditions matter and mechanical rescue is bounded; a universal cellular-stress trigger for vascular development is not isolated.'],
   ['4.3', 'qualified', 'VEGF/VEGFR and mechanical-response signaling have defined evidence, while the complete required signaling set and generic two-cell threshold remain unestablished.']],
  ['Direct exchange/oxygen delivery, complete lumen/pruning mechanisms, all organ-specific vascular architectures and resolved adult mural-cell taxonomy require further source-bound work.']);

card(7, 'Nervous System and Physiological Coordination of Organs', 'neural-organ-coordination-scope',
  'Neural physiological coordination is reconstructed through genetically targeted mouse thermoregulatory and thirst circuits plus distinct cerebral vascular response assays. Neural perturbations can alter multiple bounded effectors or reversibly change drinking. Existing differentiated circuits are the bearers; the data do not construct a full nervous system, prove every reflex arc or pathfinding mechanism, or require higher cognition. Neural, endocrine and behavioral endpoints can all act rapidly, so a universal fast-neural/slow-hormone split is excluded.',
  ['thermal-neural-stimulation-input', 'coordinated-thermal-effectors', 'drinking-suppression-recovery', 'hall-sensory-perfusion-response', 'hill-awake-neurovascular-response', 'neuroendocrine-fast-slow-boundary'],
  [['Anatomically organized excitable neural coordination', 'supported', 'Identified targeted populations and projection/localization controls supply scoped circuit bearers with intervention-linked outputs.'],
   ['Rapid timing and multiple physiological effectors', 'supported', 'Thermal endpoints and timed drinking/vascular responses have explicit finite acquisition windows; no common universal delay is imposed.'],
   ['Neural/glial differentiation, synapses, pathfinding and stabilization', 'qualified', 'Existing neuronal specialization and circuit targeting are used. Complete neural development, glial necessity, every synapse and stabilization mechanism are not tested by these functional assays.'],
   ['Reflex arcs, autonomic branches and organ synchronization', 'qualified', 'Selected autonomic thermal coordination and fluid-control behavior are demonstrated; no exhaustive reflex map or phase synchronization of all organs is measured.'],
   ['Neural control preserves slower regulation after lesion', 'unresolved', 'Reversible specific silencing differs from whole-system lesions; preserved hormonal/cellular function across every neural disruption is not established.'],
   ['Hormonal regulation is always slower', 'excluded', 'Vasopressin-neuron predictive responses occur within seconds and endocrine oscillatory dynamics have their own timescales.'],
   ['Physiological function implies cognitive planning', 'excluded', 'The selected physiological assays do not require a higher cognitive ontology or infer conscious planning.']],
  [['5.0', 'qualified', 'Established tissue/circuit anatomy provides the preparation; neural architecture formation is not reconstructed by functional sufficiency experiments.'],
   ['4.3', 'qualified', 'Specific neural signaling interventions support local function, without a generic cellular-communication weight or complete mechanism.'],
   ['4.5', 'qualified', 'The bearers are already specialized neurons; necessity/sufficiency of every differentiation program for a complete nervous system remains untested.']],
  ['A full nervous-system construction sequence, complete autonomic/reflex loops and quantified inter-organ phase coordination remain open.']);

card(8, 'Endocrine Regulation and Hormonal Systems', 'endocrine-system-scope',
  'Endocrine organization is reconstructed using rat CRH-pituitary-adrenal hormone dynamics, timed circulating corticosterone-to-liver transcription and measured mouse vasopressin-neuron anticipation. Glands, hormone concentrations, target machinery and feedback models are kept distinct from their measured outputs. Dose and exposure history can change temporal regime; endocrine action is not intrinsically one slow scalar channel. Formation of all glands and control of every growth, reproductive, stress and metabolic program are not inferred from these selected axes.',
  ['dose-dependent-endocrine-regime', 'endocrine-sampling-phase-boundary', 'hpa-model-versus-mechanism', 'rat-hormone-replacement-input', 'liver-transcription-response', 'renal-output-inference-boundary'],
  [['Specialized secretion, circulation and target recognition', 'qualified', 'The source preparations measure selected circulating hormones and hepatic GR-associated responses; vasopressin neuron identity is not itself simultaneous hormone secretion measurement.'],
   ['Persistent systemic anatomical regulatory network', 'qualified', 'Existing pituitary/adrenal/liver relationships provide a scoped architecture; their full development and a universal endocrine-object boundary are not experimentally reconstructed.'],
   ['Concentration dependence and feedback stabilization', 'qualified', 'CRH dose and corticosterone schedule alter measured output. The complete feedback generator remains a compatible model, not uniquely identified mechanism or exact stable-range law.'],
   ['Slow, sustained endocrine coordination versus rapid neural action', 'excluded', 'Hormonal release, neural source activity, receptor dynamics and gene readouts have distinct overlapping timescales; the categorical speed split is not general.'],
   ['Growth, metabolism, reproduction and stress in one architecture', 'qualified', 'Selected HPA and hepatic gene responses are admitted; reproductive/growth axes and all organismal consequences require additional primary preparations.'],
   ['Gland removal or receptor blockade universally leaves neural control intact', 'unresolved', 'Adrenalectomy with replacement is a specific context and not a complete test of preserved neural physiology after every endocrine lesion.']],
  [['5.0', 'qualified', 'Existing glands/tissue anatomy is part of the bearer; the experiments do not establish a universal morphogenetic sequence.'],
   ['4.3', 'qualified', 'Specific CRH/ACTH/GR contexts carry evidence; an abstract signaling parent is not an experimentally measured common weight.'],
   ['4.5', 'qualified', 'Specialized endocrine/target cells are present, but the necessary full differentiation program is not isolated here.']],
  ['Full gland development, direct renal hormone-output coupling and additional reproductive/growth axes remain outside these source scopes.']);
card(12, 'Hormonal–Neural Integration (Neuroendocrine System)', 'neuroendocrine-integration-scope',
  'Neuroendocrine integration is reconstructed as source-bound relationships between identified neural populations, systemic cues and hormone dynamics. Mouse VPpp activity predicts selected ingestive consequences; rat pituitary-adrenal output can oscillate under constant CRH drive, and timed glucocorticoid replacement changes hepatic transcription. These are distinct preparations, not one experimentally closed bidirectional whole-organism loop. The pattern concept organizes comparisons without inventing new physical links between different species or studies.',
  ['vasopressin-neuron-anticipation', 'vasopressin-bidirectional-ingestion', 'renal-output-inference-boundary', 'dose-dependent-endocrine-regime', 'endocrine-sampling-phase-boundary', 'hpa-model-versus-mechanism', 'liver-transcription-response'],
  [['Neural and endocrine systems are coupled', 'supported', 'Genetically identified pituitary-projecting neuroendocrine neurons and measured CRH/ACTH/corticosterone contexts provide concrete interfaces, with each acquisition boundary retained.'],
   ['Shared regulation across multiple temporal scales', 'qualified', 'Second-scale neural activity, minute-scale hormone dynamics and transcriptional readouts are measured separately; a universal two-timescale controller is not inferred.'],
   ['Bidirectional feedback and shared physiological variables', 'qualified', 'HPA feedback is a source model supported by selected temporal interventions. Complete bidirectional neural-hormonal-to-organ feedback is not measured end to end in one case.'],
   ['Unified regulatory closure and guaranteed stable regime', 'excluded', 'A collection of compatible source findings does not establish full control-loop closure, guarantee stable physiology or identify one universal organizing equation.'],
   ['Growth, reproduction, stress and metabolism all integrated', 'qualified', 'The selected fluid/HPA/transcription cases sample the broad concept; complete reproductive/growth control and all tissue targets are not admitted.'],
   ['Distributed pattern rather than a discrete object', 'qualified', 'This is an explicit scoped vocabulary choice. It does not itself prove a new ontological stage or an independent emergent causal variable.'],
   ['Coordination requires cognitive planning', 'excluded', 'No cognitive mechanism or planning-level claim follows from these physiological recordings and interventions.']],
  [['5.7', 'qualified', 'Identified neural bearers participate in neuroendocrine function, but the generic nervous-system card is not a separately measured causal fraction or every neural circuit.'],
   ['5.8', 'qualified', 'Specific hormone pathways are included; a complete endocrine-system object is not independently manipulated as a scalar parent.'],
   ['5.5', 'qualified', 'Homeostasis describes the regulated functional context rather than an independently established necessary upstream cause of every coupling event.']],
  ['Simultaneous neural activity, circulating hormone, organ effector and regulated-variable measurements under matched perturbation are required before claiming complete closure.']);

card(14, 'Trophic Regulation of Cellular Metabolism', 'trophic-metabolic-scope',
  'Trophic metabolic regulation is reconstructed through actual extracellular nutrient/media changes, a matched xCT genetic contrast and an acute systemic cystine-to-xenograft labeling experiment. These establish conditional supply/transport/metabolism relationships, alongside a direct cell-free urate/UMPS contribution and drug-specific response limits. They do not prove purposive downward optimization, universal dependence on inflammatory context or that cell isolation reproduces an entire physiological regulatory envelope. Hormonal gene responses are a separate source context, not an unmeasured metabolic flux.',
  ['nutrient-dependent-metabolic-use', 'xct-conditioned-labeling-output', 'plasma-cystine-availability', 'tumor-nutrient-labeling-response', 'metabolic-reorganization-retained-charge', 'urate-pyrimidine-cell-output', 'umps-product-inhibition-output', 'drug-specific-context-sensitivity'],
  [['Extracellular supply changes cellular pathway use', 'supported', 'Defined medium, cystine/urate and transporter perturbations alter actual metabolic readouts in their specified cells.'],
   ['Organism-scale supply can constrain tissue-cell metabolism', 'qualified', 'Acute systemic cystine intervention changes a terminal tumor-labeling endpoint; separate plasma availability and hypothetical trajectory panels cannot identify a tumor-labeling rate. Normal organ-demand allocation, chronic optimization and complete trophic architecture are not measured.'],
   ['Hormonal, growth-factor, immune and local-environment contributions', 'qualified', 'Selected nutrient/metabolite effects are isolated, while serum still contains growth support. Every hormone, growth factor or inflammatory factor is not independently identified in these experiments.'],
   ['Higher-level envelope dominates intracellular optimization', 'excluded', 'No unique intracellular optimum or objective function is measured. xCT conditioning and purified-enzyme response show concrete physical interactions rather than a separate universal downward law.'],
   ['Stable energetic allocation and all metabolic states shift together', 'excluded', 'HPLM changes multiple pathways while measured energy charge is retained; readouts are cell- and drug-dependent.'],
   ['Cell removal and reinsertion prove general context causation', 'qualified', 'Culture versus xenograft comparisons motivate matched nutrient interventions, but isolation changes many factors and is not by itself a unique causal test.'],
   ['Persistent property of higher organization', 'qualified', 'The capacity label is a descriptive scope; acute assays do not prove an autonomous persistent global regulatory variable.']],
  [['5.5', 'qualified', 'Systemic availability can constrain cellular chemistry, while the selected acute tumor intervention does not establish a complete organ-homeostatic controller.'],
   ['4.2', 'qualified', 'Existing metabolic machinery and transport are bearers of response; the broad metabolism category supplies no independent causal weight.'],
   ['5.22', 'unresolved', 'Tissue inflammatory microenvironments are not independently varied in these selected nutrient/medium cases.'],
   ['5.24', 'excluded', 'Chronic low-grade inflammation is not necessary for the admitted cultured-cell or purified-enzyme responses.'],
   ['5.25', 'unresolved', 'Immune resilience/constraint trade-offs are not measured as causes of these metabolic responses.'],
   ['5.27', 'unresolved', 'A closed inflammation-metabolism feedback loop is not measured here; joining separate nutrient and inflammation cases would not prove reciprocity.']],
  ['Matched normal-tissue allocation, direct endocrine-to-metabolic-flux tests and complete immune/nutrient feedback require additional distinct preparations.']);

card(16, 'Neuroendocrine Influence on Gene Expression', 'neuroendocrine-gene-expression-scope',
  'Neuroendocrine expression influence is reconstructed with ligand-dependent GR promoter dynamics, separate pulsed/constant cell RNA and protein assays, and a systemic corticosterone-to-rat-liver transcription experiment. Hormone identity, dose, cumulative exposure, receptor occupancy, nascent RNA, mature RNA and protein are not interchangeable. The existing physiological source architecture provides context, while an unmeasured direct neural-to-chromatin path, heritable epigenetic rewrite, all tissue programs and a universal stable regulatory envelope remain unestablished.',
  ['gr-ligand-specific-dynamics', 'hormone-transcription-pulsing', 'hormone-rna-protein-boundary', 'liver-transcription-response', 'hpa-model-versus-mechanism'],
  [['Systemic hormonal input changes cellular gene output', 'supported', 'Timed circulating corticosterone replacement produces measured hepatic GR-associated and Per1 transcriptional responses in a declared animal preparation.'],
   ['Neural timing, receptor recognition and expression machinery integrate', 'qualified', 'HPA context and separate GR transcription studies support a comparative connection, not one measured full neural-to-transcription causal chain.'],
   ['Transcription, chromatin-associated binding and epigenetic change', 'qualified', 'GR/Pol-II binding and selected transcriptional outputs are measured. Stable chromatin modification, inherited epigenetic state and all second-messenger pathways are not established by promoter occupancy.'],
   ['Pulse pattern is causal independent of exposure', 'excluded', 'The principal pulse-versus-constant schedules change cumulative exposure as well as timing; a frequency-only interpretation is not identified.'],
   ['All physiological demands and tissue expression programs', 'qualified', 'Selected HPA-related targets and liver provide bounded examples, without a complete growth/reproduction/stress/metabolic program atlas.'],
   ['Expression changes without changing DNA sequence', 'qualified', 'The acute interventions do not require deliberate genomic sequence editing to alter expression, but no genome-wide sequence-integrity assay was performed.'],
   ['Persistent higher-level regulatory capacity', 'qualified', 'An operationally scoped capacity can be named, but finite pulses do not prove an independent stable global envelope or lifetime persistence.']],
  [['5.7', 'qualified', 'Neural HPA organization is contextual; direct neural intervention and hepatic expression are not tested as one matched complete chain in these cases.'],
   ['5.8', 'qualified', 'Specific circulating glucocorticoid input is tested, without transferring generic endocrine necessity or a common contribution fraction.'],
   ['4.8', 'qualified', 'Existing cellular transcription machinery carries the response, but a generic gene-regulation card is not a separately isolated causal parent.']],
  ['Direct matched neural-to-hormone-to-expression tests, dose-matched waveform comparisons and measured chromatin-state persistence remain open.']);

card(17, 'Neural Regulation of Proliferative State in Target Tissues', 'neural-proliferative-control-scope',
  'Neural proliferative influence is reconstructed by descriptive reuse of the existing adult mouse PV-RGL cycle-marker evidence and an independent mouse cutaneous-denervation niche study. The former has bidirectional stimulation/inhibition contrasts and incomplete housing-effect rescue; the latter separates loss of Gli1 identity from retained telogen quiescence, one regeneration cycle and acute wound closure, while later labeled-lineage retention falls. These are selected target compartments with different outputs, not universal neural control of all division or a measured common proliferative threshold.',
  ['existing-neural-cycle-evidence', 'neural-marker-not-proliferation', 'hair-cycle-neural-necessity-boundary', 'acute-repair-versus-lineage-retention'],
  [['Neural influence on selected target-cell cycling', 'supported', 'Previously reconstructed PV activation/inhibition changes RGL cycle markers in adult dentate tissue; the source and its unresolved controls are reused without claiming independent replication.'],
   ['Quiescence, readiness, checkpoint passage and division timing', 'qualified', 'EdU/MCM2 and finite niche/lineage observations support selected aspects, not direct universal threshold, checkpoint transit or completed-division timing measurements.'],
   ['Neurotransmitters, peptides and neuroendocrine routes', 'qualified', 'The reviewed PV/GABA and nerve-associated Hedgehog cases are distinct mechanisms; every peptide or systemic endocrine proliferative route is not established.'],
   ['Regeneration and renewal follow one neural necessity rule', 'excluded', 'Denervation changes molecular identity and long-term lineage retention while selected quiescence, one hair cycle and early wound healing remain preserved.'],
   ['Organismal stress, circadian, sensory and injury context', 'qualified', 'Existing housing and injury comparisons provide bounded history/context evidence. A complete stress/circadian/sensory-to-niche causal atlas is not constructed.'],
   ['Perturbations leave baseline local machinery unchanged', 'unresolved', 'Neither denervation nor prolonged neural manipulation proves that every local molecular/vascular/immune variable is unchanged; alternative mediated effects remain possible.'],
   ['Higher-level stable property applies to all tissues', 'excluded', 'The original card itself limits the claim to selected responsive targets; no universal downwards division controller or lifetime possession theorem is admitted.']],
  [['5.7', 'qualified', 'Specified existing neural bearers affect selected targets, not the complete nervous system as a universally necessary scalar input.'],
   ['4.4', 'qualified', 'Cycle-related markers and finite lineage consequences differ from direct checkpoint/division measurement; apoptosis is separately assessed and not a required step in every response.']],
  ['Independent animal-level reanalysis of existing Song assays, direct proliferation versus survival/migration separation and more target tissues are required before wider transfer.']);

function comparison(id, candidate, alternative, findingIds, discriminator, limit) {
  const sourceIds = [...new Set(findingIds.flatMap((id) => {
    const f = findingIndex.get(id); return f.studyId ? [studyIndex.get(f.studyId).record.sourceId] : f.sourceIds;
  }))];
  comparisons.push({ id, candidate, alternative, sourceIds, discriminator, result: 'conditional-support', limit,
    assumptions: ['Keep species, preparation, intervention, dose, readout and acquisition time explicit.', 'Preparations from one publication and reused existing evidence do not become independent replications.', commonLimit],
    claimIds: findingIds.map((id) => findingIndex.get(id).claimId) });
}
comparison('organismal-vascular-organization-versus-components', 'Guidance and force conditions influence an already assembled vascular system, and anatomical presence does not guarantee transport function.', 'More VEGF, visible vessels or distributed blood cells are sufficient to establish an effective normal transport network.', ['vascular-guidance-versus-growth', 'circulation-not-cell-presence', 'vascular-remodeling-rescue'], 'Compare spatial VEGF perturbations, live trajectories/plasma transport and viscosity rescue rather than substituting static structure for function.', 'The different retinal and yolk-sac preparations do not supply one universal quantitative network law or all tissue oxygen-delivery outcomes.');
comparison('organismal-mural-perfusion-attribution', 'Adult neurovascular response attribution depends on mural-cell classification, physiological state and actual assay.', 'Every early small-diameter branch is the same pericyte-controlled capillary and all papers identify one common mechanism.', ['hall-sensory-perfusion-response', 'hall-pericyte-attribution-boundary', 'mural-contractility-positive-and-null', 'hill-awake-neurovascular-response'], 'Preserve Hall anesthesia/electrical stimulation and Hill SMA/morphology/awake-air-puff distinctions, and require a matched discriminator before declaring reconciliation.', 'The record retains a cross-study mechanistic disagreement; it does not decide a universal winner or introduce a synthetic consensus causal edge.');
comparison('organismal-anticipation-versus-restoration', 'Predictive neural signals and behavior can change before systemic correction, with input- and cell-type-dependent cue responses.', 'Every homeostatic signal is a delayed negative-feedback readout of already corrected blood composition.', ['anticipation-precedes-blood-correction', 'saline-prediction-reversal', 'vasopressin-neuron-anticipation', 'vasopressin-bidirectional-ingestion'], 'Measure cue, ingestion, neural activity and blood dynamics separately; water-cue response in VPpp neurons differs from the tested SFO cue null.', 'Different cell populations/studies are not contradictory measures of one identical neuron, and the renal effector remains unmeasured here.');
comparison('organismal-endocrine-temporal-encoding', 'Dose, ligand identity and exposure history condition endocrine output dynamics.', 'A hormone is a uniformly slow concentration-only channel whose output simply copies neural pulses.', ['dose-dependent-endocrine-regime', 'hpa-model-versus-mechanism', 'gr-ligand-specific-dynamics', 'hormone-transcription-pulsing'], 'Constant CRH can generate oscillatory or damped hormone output; natural/synthetic ligand withdrawal and distinct transcription schedules have different measured responses.', 'Cross-study temporal comparison is descriptive; unequal cumulative exposure prevents a frequency-only claim, and no single feedback mechanism is uniquely identified.');
comparison('organismal-supply-times-cell-state', 'Extracellular nutrient effects depend on transport/cell state and can change selected outputs while preserving others.', 'An identical external environment imposes one universal metabolic regime independently of cellular machinery.', ['xct-conditioned-labeling-output', 'tumor-nutrient-labeling-response', 'metabolic-reorganization-retained-charge', 'drug-specific-context-sensitivity'], 'Use matched knockdown/rescue and nutrient/dropout controls, retaining energy-charge and drug-specific nulls rather than assuming global metabolic failure.', 'Culture, xenograft, purified enzyme and drug assays have distinct units; common vocabulary does not prove a full organismal resource-allocation objective.');
comparison('organismal-neural-niche-specificity', 'Neural influence is compartment-, endpoint- and time-dependent.', 'Neural input is uniformly necessary for every proliferative transition or all wound regeneration.', ['existing-neural-cycle-evidence', 'neural-marker-not-proliferation', 'hair-cycle-neural-necessity-boundary', 'acute-repair-versus-lineage-retention'], 'Compare neural-cycle-marker perturbation with denervation that changes niche identity while preserving selected early renewal and altering later lineage persistence.', 'Song is reused evidence, not a new replication; reporter identity and labeled-area retention are not direct counts of completed division.');

